"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0961-03-06:0":{"b": ["Kandiya süquta uğradı: Nikephoros Phokas Kriti geri aldı", "aeefb280"], "d": ["Nikephoros Phokasın komandanlığı altındakı Bizans qüvvələri bir il davam edən mühasirədən sonra 6 mart 961-də Kandiyanı ələ keçirdi; təxminən 130 il davam edən Krit əmirliyi sona çatdı. Adanın müsəlman əhalisinin bir hissəsi adanı tərk etdi, bir hissəsi dinini dəyişməyə məcbur edildi.", "ec04c12b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0962-01-01:0":{"b": ["Əhməd ibn Həsən əl-Kəlbi yeddi aylıq mühasirədən sonra Bizansın Taormina qalasını alıb adını Müizziyyə qoydu", "37e8ae59"], "d": ["Əhməd ibn Həsən əl-Kəlbi yeddi aylıq mühasirədən sonra Bizansın Taormina qalasını alıb adını Müizziyyə qoyur.", "f8fcc7b1"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-01-01:0":{"b": ["Nikephoros Phokas Missisa və Tarsusu işğal etdi (354/965).", "045053b4"], "d": ["Nikephoros Phokas Missisa və Tarsusu işğal etdi (354/965).", "045053b4"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-08-16:0":{"b": ["Tarsus Bizansa təslim oldu: Kilikiya Bizans hakimiyyətinə girdi", "b05e9bd3"], "d": ["Missis (Mopsuestia) 965-ci ilin iyulunda, Tarsus bir ay sonra 16 avqust 965-də insani şərtlərlə təslim oldu və yenidən xristian şəhəri oldu. Beləliklə Kilikiya bölgəsi Bizansa qatıldı.", "faeb461f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0969-10-28:0":{"b": ["Antakya Bizansın əlinə keçdi", "ad0a5da3"], "d": ["Bizans orduları Şimali Suriyada çoxlu qala və şəhər aldıqdan sonra Kilikiyadan gələn Michael Burtzes və Petros Phokas Antakyanı 28 oktyabr 969-da ələ keçirdi. Şəhər təxminən 115 il boyunca Bizansın Suriyadakı əsas bazası oldu.", "38b840e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0971-04-13:0":{"b": ["Tzimiskes Böyük Preslavı hücumla aldı: Şərqi Bulqarıstan Bizansa qatıldı", "07c84840"], "d": ["Ioannes Tzimiskes 971-ci il aprelin 12-də Preslav ovasına daxil oldu; aprelin 13-ü axşamı Svyatoslavın adamlarının müdafiə etdiyi Bulqar paytaxtı süquta uğradı. Çar Boris əsir alındı və Bizans idarəsi Frakiya ilə Şərqi Bulqarıstana yayıldı.", "ae050b34"]},
