"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1160-01-21:0":{"b": ["Müvəhhidlər Mehdiyyəni Normanlardan geri aldı", "a195fa3d"], "d": ["Mehdiyyə, Həsən b. Əlinin təşviqi ilə 10 Müharrəm 555-də (21 yanvar 1160) Normanlardan geri alınıb Müvəhhid valisinə verildi.", "96c396ce"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1163-01-01:0":{"b": ["Əbdülmöuminin ölümündən sonra oğlu Yusuf b. Əbdülmöumin xəlifə olur (1163-1184).", "dfcc2ec9"], "d": ["Əbdülmöuminin ölümündən sonra oğlu Yusuf b. Əbdülmöumin xəlifə olur (1163-1184).", "dfcc2ec9"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1163-05-16:0":{"b": ["Əbdülmöumin Salada öldü; yerinə Əbu Yəqub Yusuf keçdi", "231a4a53"], "d": ["Əndəlüs yürüşü üçün Ribatülfəthə gələn Əbdülmöumin xəstələnib 10 Cəmadiyəlaxir 558-də (16 may 1163) Salada öldü; ordu hazırlığı yarımçıq qaldı, oğlu Yusuf xəlifə oldu.", "58390143"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1183-04-26:0":{"b": ["Yusuf b. Əbdülmöumin Şəntərin və Üşbunəni (Lissabon) mühasirəyə aldı", "1da17da0"], "d": ["Kastiliya ilə əməkdaşlıq edən Yusuf, müsəlman şəhərlərini narahat edən portuqaliyalıları cəzalandırmaq üçün 579 (1183) ilində əvvəlcə Şəntərini (Santarém), ardınca Üşbunəni mühasirəyə aldı; ağır yaralanıb ölünçə yürüş yarımçıq qaldı.", "cbbc3194"]},
