"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1229-11-20:0":{"b": ["Hafsi Əbu Zəkəriyyə Müvəhhidlərdən müstəqilliyini elan etdi", "d1f63c2f"], "d": ["Əbu Zəkəriyyə, 627-ci ilin əvvəlində Müvəhhid xəlifəsi İdris əl-Məmunun inanclarının Əhli-sünnətə zidd olduğunu irəli sürüb xütbəni kəsdi və 'əmir' titulu ilə müstəqilliyini elan edərək Hafsi sülaləsinin həqiqi qurucusu oldu.", "74908f3f"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1235-01-01:0":{"b": ["Yağmurasan b. Zeyyan Tilimsanda Əbdülvadi (Zeyyani) sülaləsini qurdu", "5c80da4e"], "d": ["Müvəhhidlərin zəiflədiyi bir dövrdə Bəni Əbdülvad bərbərlərinin başçısı Yağmurasan b. Zeyyan, Tilimsanda sülalə qurdu (632/1235).", "7f35119e"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1236-01-01:0":{"b": ["III Fernando Kordobanı aldı", "1431c9e8"], "d": ["Zəif vəziyyətdəki Kordoba, Kastiliya-Leon kralı III Fernando tərəfindən 1236-da asanlıqla zəbt edildi; Hudilər idarəsindən sonra şəhər xristian hakimiyyətinə girdi.", "883b568e"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1246-01-01:0":{"b": ["Ğalib-Billah Kastiliyaya bağlılığı qəbul edib Cəyyanı tərk etdi", "754718f2"], "d": ["Nəsri qurucusu I Məhəmməd, Cəyyan müdafiəsində çarəsiz qalınca Kastiliya kralının hakimiyyətini tanımaq, Cəyyanı və bəzi qalaları tərk etmək, illik vergi ödəmək şərti ilə müqavilə imzaladı (643/1246).", "28a8266d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1255-02-10:0":{"b": ["Mərinilər Fəs yaxınlığında 80.000 nəfərlik Müvəhhid ordusunu məğlub etdi", "d88fb0f0"], "d": ["Əbu Yəhya Əbu Bəkr 653 (1255) ilində Fəs yaxınlığında Müvəhhid ordusunu məğlub etdi; Müvəhhidlərin hakimiyyəti Mərakeş bölgəsi ilə məhdud qaldı.", "b1248952"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1263-01-01:0":{"b": ["Əbu Yusuf Yəqub Mərakeşi mühasirəyə aldı, lakin ələ keçirə bilmədi", "8140e358"], "d": ["Mərini sultanı Əbu Yusuf Yəqub 661 (1263) ilində böyük ordu ilə Müvəhhidlərin paytaxtı Mərakeşi mühasirəyə aldı, lakin ələ keçirə bilmədi.", "11966886"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1264-10-24:0":{"b": ["Mürsiyə əhalisi Nəsrilərin təşviqi ilə üsyan etdi", "ee46ead4"], "d": ["Nəsri idarəçilərinin təşviqi ilə Mürsiyə əhalisi 663-də (1264-65) Kastiliyaya qarşı bir daha üsyan etdi.", "4feae798"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1266-01-01:0":{"b": ["Araqon kralı I Jaime Mürsiyəni Kastiliya adına ələ keçirdi", "b9b3701f"], "d": ["Kastiliyalıların çağırışı üzərinə köməyə gələn Araqon kralı I Jaime üsyan edən Mürsiyəni iki il sonra (təxminən 1266) aldı; X Alfonso müsəlmanları qırx gün içində şəhər mərkəzindən çıxartdı.", "049fb942"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1269-09-09:0":{"b": ["Mərini sultanı Əbu Yusuf Mərakeşə girdi; Müvəhhid dövləti sona çatdı", "a0d8bd46"], "d": ["Mərini Sultanı Əbu Yusuf Yəqub 10 Müharrəm 668-də (9 sentyabr 1269) Mərakeşə girib yeddi ay qaldı; Müvəhhid xəlifəsi Əbu Dəbbus və Mərakeşdə qalan Müvəhhid ağsaqqalları bu zaman aradan götürüldü.", "dea7284f"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1275-09-08:0":{"b": ["Mərinilər Écija (İsticə) döyüşündə Don Nuño de Laranın Kastiliya ordusunu məğlub etdi", "77d0e14e"], "d": ["Əbu Yusuf Yəqub Əndəlüsə keçib Kordoba yaxınlığındakı İsticədə Kastiliya ordusunu məğlub etdi (15 Rəbiüləvvəl 674 / 8 sentyabr 1275); çoxlu əsir və qənimət aldı.", "94faa00f"]},
